import GallerySectionV2 from "./components/gallery-section-v2"

export default function Page() {
  return <GallerySectionV2 />
}

import { GalleryCard } from "./gallery-card"
import { galleryFiles, type GalleryItem } from "../lib/config"

const mediaOrigin = process.env.NEXT_PUBLIC_BASE_URL ?? "https://uiception.com"
const blockImage = (filename: string) =>
  `${mediaOrigin}/images/blocks/gallery-section-v2/${filename}`

const galleryItems: GalleryItem[] = galleryFiles.map(
  ({ file, ...rest }, index) => ({
    id: String(index + 1),
    ...rest,
    imageSrc: blockImage(file),
  }),
)

export default function GallerySectionV2() {
  return (
    <section className="py-4 md:py-6 lg:py-8">
      <div className="mx-auto max-w-7xl px-4">
        <h2 className="mb-6 font-mono text-4xl lg:text-5xl">
          Gallery
        </h2>
        <div className="grid grid-cols-3 gap-x-6 gap-y-10">
          {galleryItems.map((item, index) => (
            <GalleryCard
              key={item.id}
              item={item}
              priority={index < 3}
            />
          ))}
        </div>
      </div>
    </section>
  )
}

"use client"

import { useState } from "react"
import Image from "next/image"

import type { GalleryItem } from "../lib/config"

type GalleryCardProps = { item: GalleryItem; priority?: boolean }

export function GalleryCard({ item, priority = false }: GalleryCardProps) {
  const [loaded, setLoaded] = useState(false)

  return (
    <div className="group">
      <div className="relative isolate aspect-4/3 overflow-hidden">
        <Image
          src={item.imageSrc}
          alt={item.alt}
          fill
          unoptimized
          priority={priority}
          sizes="(max-width: 768px) 50vw, 33vw"
          className={`object-cover transition-opacity duration-500${loaded ? " opacity-100" : " opacity-0"}`}
          onLoad={() => setLoaded(true)}
          onError={() => setLoaded(true)}
        />
        {loaded && (
          <div
            aria-hidden
            className="pointer-events-none absolute inset-0 bg-[#808080] mix-blend-color transition-opacity duration-500 group-hover:opacity-0"
          />
        )}
      </div>
      <div className="mt-3 font-mono">
        <p className="text-sm font-medium leading-tight">{item.title}</p>
        <p className="mt-1 text-xs text-muted-foreground">{item.description}</p>
      </div>
    </div>
  )
}
